// Determine crawl round and page count based on trigger source
const now = new Date();
// Bangkok time offset UTC+7
const utcHour = now.getUTCHours();
const bkkHour = (utcHour + 7) % 24;

let crawlRound = '12:00';
let totalPages = 20;
let crawlMode = 'shallow';

const triggerNode = $input.first().json;

if (bkkHour >= 23 || bkkHour <= 2) {
  crawlRound = '00:00';
  totalPages = 80;
  crawlMode = 'deep';
} else if (bkkHour >= 5 && bkkHour <= 8) {
  crawlRound = '06:00';
  totalPages = 20;
  crawlMode = 'shallow';
} else if (bkkHour >= 11 && bkkHour <= 14) {
  crawlRound = '12:00';
  totalPages = 20;
  crawlMode = 'shallow';
} else if (bkkHour >= 17 && bkkHour <= 20) {
  crawlRound = '18:00';
  totalPages = 20;
  crawlMode = 'shallow';
}

// Support manual override parameters if provided
if (triggerNode && triggerNode.customPages) {
  totalPages = Number(triggerNode.customPages) || totalPages;
}
if (triggerNode && triggerNode.customRound) {
  crawlRound = String(triggerNode.customRound);
}

return [
  {
    json: {
      crawlRound,
      totalPages,
      crawlMode,
      startedAt: now.toISOString(),
      scrapedProducts: [],
      successPages: 0,
      failedPages: 0
    }
  }
];

const crawlLog = $input.first().json;
const crawlLogId = Array.isArray(crawlLog) ? crawlLog[0].id : (crawlLog.id || 'dev-crawl-log');
const initData = $('Initialize Crawl Scope & Round').first().json;
const totalPages = initData.totalPages || 20;

// Generate array of page items for sequential processing
const pageItems = [];
for (let p = 1; p <= totalPages; p++) {
  pageItems.push({
    json: {
      crawlLogId,
      crawlRound: initData.crawlRound,
      page: p,
      totalPages,
      crawlMode: initData.crawlMode
    }
  });
}

return pageItems;

const item = $input.first().json;
const page = item.page;

// Jitter Delay: Randomized between 3 and 7 seconds (3.0s - 7.0s)
const jitterSeconds = +(Math.random() * (7.0 - 3.0) + 3.0).toFixed(2);

// Cool-off Pause: 25 seconds after every 10 fetched pages (e.g. before page 11, 21, 31...)
let coolOffSeconds = 0;
let isCoolOffActive = false;

if (page > 1 && (page - 1) % 10 === 0) {
  coolOffSeconds = 25;
  isCoolOffActive = true;
}

// First page executes with minimal warmup jitter, subsequent pages apply calculated delay
const totalDelaySeconds = page === 1 ? 0.5 : +(coolOffSeconds + jitterSeconds).toFixed(2);

return [
  {
    json: {
      ...item,
      jitterSeconds,
      coolOffSeconds,
      isCoolOffActive,
      totalDelaySeconds,
      totalDelayMs: Math.round(totalDelaySeconds * 1000)
    }
  }
];

const response = $input.first().json;
const pageContext = $('Calculate Jitter Delay & Cool-Off Pause').first().json;

// Inspect HTTP status code (handling both full response object and error structures)
const statusCode = response.statusCode || (response.error && response.error.status) || 200;
const isForbiddenOrRateLimited = statusCode === 403 || statusCode === 429;

let products = [];
if (!isForbiddenOrRateLimited && response.body) {
  if (Array.isArray(response.body.data)) {
    products = response.body.data;
  } else if (response.body.data && Array.isArray(response.body.data.list)) {
    products = response.body.data.list;
  } else if (Array.isArray(response.body.items)) {
    products = response.body.items;
  }
}

return [
  {
    json: {
      ...pageContext,
      statusCode,
      isForbiddenOrRateLimited,
      itemCount: products.length,
      products,
      timestamp: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

// Collect products from successful page
return [
  {
    json: {
      crawlLogId: item.crawlLogId,
      crawlRound: item.crawlRound,
      page: item.page,
      totalPages: item.totalPages,
      products: item.products || []
    }
  }
];

// Aggregate all fetched products across all successful pages
const allPageResults = $input.all();
const allProducts = [];
let crawlLogId = '';
let crawlRound = '';
let totalPages = 0;

for (const res of allPageResults) {
  const data = res.json;
  if (data.products && Array.isArray(data.products)) {
    allProducts.push(...data.products);
  }
  if (data.crawlLogId) crawlLogId = data.crawlLogId;
  if (data.crawlRound) crawlRound = data.crawlRound;
  if (data.totalPages) totalPages = data.totalPages;
}

return [
  {
    json: {
      crawlLogId,
      crawlRound,
      totalPagesRequested: totalPages,
      totalPagesSuccess: allPageResults.length,
      rawProductsScraped: allProducts.length,
      products: allProducts,
      completedScrapeAt: new Date().toISOString()
    }
  }
];

const inputData = $input.first().json;
const rawProducts = inputData.products || [];
const crawlLogId = inputData.crawlLogId;
const crawlRound = inputData.crawlRound;
const totalPagesRequested = inputData.totalPagesRequested || 0;
const totalPagesSuccess = inputData.totalPagesSuccess || 0;
const rawProductsScraped = inputData.rawProductsScraped || rawProducts.length;

function parsePrice(val) {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  const cleaned = String(val).replace(/[^0-9.]/g, '');
  return parseFloat(cleaned) || 0;
}

function parseCommission(val) {
  if (typeof val === 'number') {
    return val > 0 && val <= 1.0 ? +(val * 100).toFixed(2) : +val.toFixed(2);
  }
  if (!val) return 0;
  const cleaned = String(val).replace(/[^0-9.]/g, '');
  const num = parseFloat(cleaned) || 0;
  return num > 0 && num <= 1.0 ? +(num * 100).toFixed(2) : +num.toFixed(2);
}

function parseSales(val) {
  if (typeof val === 'number') return Math.round(val);
  if (!val) return 0;
  const str = String(val).toLowerCase().trim();
  if (str.endsWith('k')) {
    return Math.round(parseFloat(str.replace('k', '')) * 1000);
  }
  if (str.endsWith('m')) {
    return Math.round(parseFloat(str.replace('m', '')) * 1000000);
  }
  const cleaned = str.replace(/[^0-9]/g, '');
  return parseInt(cleaned, 10) || 0;
}

function slugify(name) {
  if (!name) return 'general';
  return String(name)
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'general';
}

const filteredProducts = [];
const categoryMap = new Map();

for (const raw of rawProducts) {
  const sourceId = String(raw.product_id || raw.id || raw.item_id || raw.goods_id || '').trim();
  if (!sourceId) continue;

  const price = parsePrice(raw.price || raw.min_price || raw.price_value);
  const commissionRate = parseCommission(raw.commission_rate || raw.commission || raw.commission_ratio);
  const totalSales = parseSales(raw.total_sales || raw.sales || raw.sold_count || raw.sales_volume);

  // Pre-Filtering Quality Gate Criteria:
  // 1. Commission >= 10%
  // 2. Price between 80 and 1,500 THB
  // 3. Total Sales >= 30
  if (commissionRate >= 10.0 && price >= 80.0 && price <= 1500.0 && totalSales >= 30) {
    const categoryName = String(raw.category_name || raw.category || raw.cate_name || 'General').trim();
    const categorySlug = slugify(categoryName);

    if (!categoryMap.has(categorySlug)) {
      categoryMap.set(categorySlug, {
        name: categoryName,
        slug: categorySlug
      });
    }

    filteredProducts.push({
      sourceId,
      name: String(raw.title || raw.product_name || raw.name || 'TikTok Product').trim(),
      imageUrl: String(raw.image_url || raw.cover || raw.image || raw.pic_url || '').trim(),
      productUrl: String(raw.product_url || raw.url || raw.detail_url || `https://shop.tiktok.com/view/product/${sourceId}`).trim(),
      categoryName,
      categorySlug,
      price: +price.toFixed(2),
      commissionRate: +commissionRate.toFixed(2),
      totalSales
    });
  }
}

const categories = Array.from(categoryMap.values());

return [
  {
    json: {
      crawlLogId,
      crawlRound,
      totalPagesRequested,
      totalPagesSuccess,
      rawProductsScraped,
      filteredProductsSaved: filteredProducts.length,
      categories,
      filteredProducts,
      hasFilteredProducts: filteredProducts.length > 0
    }
  }
];

const gateData = $('Pre-Filter Quality Gate & Taxonomy Extraction').first().json;
const filteredProducts = gateData.filteredProducts || [];
const rawCategoriesResp = $input.all();

// Map slug to category UUID returned by Supabase
const slugToId = new Map();
for (const item of rawCategoriesResp) {
  const cat = item.json;
  if (Array.isArray(cat)) {
    for (const c of cat) {
      if (c && c.slug && c.id) slugToId.set(c.slug, c.id);
    }
  } else if (cat && cat.slug && cat.id) {
    slugToId.set(cat.slug, cat.id);
  }
}

// Build products array for PostgREST upsert
const productsToUpsert = [];
const originalFilteredMap = {};
const nowIso = new Date().toISOString();

for (const p of filteredProducts) {
  const categoryId = slugToId.get(p.categorySlug) || null;
  productsToUpsert.push({
    source_id: p.sourceId,
    name: p.name,
    image_url: p.imageUrl,
    product_url: p.productUrl,
    commission_rate: p.commissionRate,
    category_id: categoryId,
    updated_at: nowIso
  });

  originalFilteredMap[p.sourceId] = {
    price: p.price,
    commissionRate: p.commissionRate,
    totalSales: p.totalSales
  };
}

return [
  {
    json: {
      crawlLogId: gateData.crawlLogId,
      crawlRound: gateData.crawlRound,
      totalPagesRequested: gateData.totalPagesRequested,
      totalPagesSuccess: gateData.totalPagesSuccess,
      rawProductsScraped: gateData.rawProductsScraped,
      filteredProductsSaved: gateData.filteredProductsSaved,
      productsToUpsert,
      originalFilteredMap
    }
  }
];

const prepData = $('Prepare Products with Category IDs').first().json;
const originalMap = prepData.originalFilteredMap || {};
const rawProductsResp = $input.all();
const crawlLogId = prepData.crawlLogId;
const nowIso = new Date().toISOString();

const snapshots = [];
for (const item of rawProductsResp) {
  const p = item.json;
  const list = Array.isArray(p) ? p : [p];
  for (const prod of list) {
    if (!prod || !prod.id || !prod.source_id) continue;
    const orig = originalMap[prod.source_id] || { price: 0, commissionRate: 0, totalSales: 0 };
    snapshots.push({
      product_id: prod.id,
      crawl_log_id: crawlLogId,
      snapshot_time: nowIso,
      price: orig.price,
      commission_rate: orig.commissionRate,
      total_sales: orig.totalSales,
      delta_sales: 0,
      velocity_per_hour: 0.00,
      winning_score: 0.00
    });
  }
}

return [
  {
    json: {
      crawlLogId,
      crawlRound: prepData.crawlRound,
      totalPagesRequested: prepData.totalPagesRequested,
      totalPagesSuccess: prepData.totalPagesSuccess,
      rawProductsScraped: prepData.rawProductsScraped,
      filteredProductsSaved: snapshots.length,
      snapshots
    }
  }
];

const gateData = $('Pre-Filter Quality Gate & Taxonomy Extraction').first().json;
let filteredSaved = 0;

try {
  const snapshotData = $('Prepare Snapshots Payload').first().json;
  filteredSaved = snapshotData.filteredProductsSaved || 0;
} catch (e) {
  filteredSaved = gateData.filteredProductsSaved || 0;
}

return [
  {
    json: {
      crawlLogId: gateData.crawlLogId,
      crawlRound: gateData.crawlRound,
      totalPagesRequested: gateData.totalPagesRequested,
      totalPagesSuccess: gateData.totalPagesSuccess,
      rawProductsScraped: gateData.rawProductsScraped,
      filteredProductsSaved: filteredSaved
    }
  }
];

const engineResult = $input.first().json;
const auditData = $('Format Audit Counts Update').first().json;

return [
  {
    json: {
      status: "SUCCESS",
      crawlLogId: auditData.crawlLogId,
      crawlRound: auditData.crawlRound,
      totalPagesRequested: auditData.totalPagesRequested,
      totalPagesSuccess: auditData.totalPagesSuccess,
      rawProductsScraped: auditData.rawProductsScraped,
      filteredProductsSaved: auditData.filteredProductsSaved,
      scoringEngineResult: engineResult,
      completedAt: new Date().toISOString()
    }
  }
];
